'use strict';

/**
* Find the indices at which elements should be inserted into a sorted strided array in order to maintain sort order.
*
* @module @stdlib/blas/ext/base/gsearch-sorted
*
* @example
* var gsearchSorted = require( '@stdlib/blas/ext/base/gsearch-sorted' );
*
* var search = [ 1.0, 2.0, 2.0, 3.0 ];
* var x = [ 0.0, 2.0, 4.0 ];
* var out = [ 0, 0, 0 ];
*
* gsearchSorted( x.length, search.length, 'left', x, 1, search, 1, out, 1 );
* // out => [ 0, 1, 4 ]
*
* @example
* var gsearchSorted = require( '@stdlib/blas/ext/base/gsearch-sorted' );
*
* var search = [ 1.0, 2.0, 2.0, 3.0 ];
* var x = [ 0.0, 2.0, 4.0 ];
* var out = [ 0, 0, 0 ];
*
* gsearchSorted.ndarray( x.length, search.length, 'right', x, 1, 0, search, 1, 0, out, 1, 0 );
* // out => [ 0, 3, 4 ]
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var main = require( './main.js' );
var ndarray = require( './ndarray.js' );


// MAIN //

setReadOnly( main, 'ndarray', ndarray );


// EXPORTS //

module.exports = main;
